"""The player cadence evolves. Each round it starts from the current champion.

It runs in its own process and is sent plain JSON each turn, so it sees only
what a player may see. Everything outside the markers stays put.
"""


# CADENCE:BEGIN
def choose(view: dict, moves: list[dict]) -> int:
    """Return one of `moves`. `view` is everything this player may see."""
    import random
    from scrabble import tools

    # Standard heuristic values for keeping tiles on the rack
    VAL = {
        "A": 1.0,
        "B": -2.0,
        "C": -0.5,
        "D": 0.5,
        "E": 2.5,
        "F": -1.5,
        "G": -0.5,
        "H": 1.0,
        "I": 0.5,
        "J": -2.5,
        "K": -1.5,
        "L": 1.0,
        "M": 1.0,
        "N": 1.5,
        "O": -0.5,
        "P": 0.5,
        "Q": -6.0,
        "R": 2.0,
        "S": 8.0,
        "T": 1.5,
        "U": -1.5,
        "V": -3.5,
        "W": -2.0,
        "X": 1.5,
        "Y": -0.5,
        "Z": -2.0,
        "?": 25.0,
    }

    # Standard Scrabble letter values for endgame penalty/bonus calculations
    TILE_VALUES = {
        "A": 1,
        "B": 3,
        "C": 3,
        "D": 2,
        "E": 1,
        "F": 4,
        "G": 2,
        "H": 4,
        "I": 1,
        "J": 8,
        "K": 5,
        "L": 1,
        "M": 3,
        "N": 1,
        "O": 1,
        "P": 3,
        "Q": 10,
        "R": 1,
        "S": 1,
        "T": 1,
        "U": 1,
        "V": 4,
        "W": 4,
        "X": 8,
        "Y": 4,
        "Z": 10,
        "?": 0,
    }

    VOWELS = {"A", "E", "I", "O", "U"}

    bag_size = view.get("bag", 100)
    if hasattr(bag_size, "__len__"):
        bag_size = len(bag_size)

    grid = view.get("grid")
    TWS = {(0, 0), (0, 7), (0, 14), (7, 0), (7, 14), (14, 0), (14, 7), (14, 14)}

    if grid:
        open_tws_board = {pos for pos in TWS if grid[pos[0]][pos[1]] is None}
    else:
        open_tws_board = TWS.copy()

    # In the endgame, unseen tiles represent exactly the opponent's rack
    unseen_score = 0
    if bag_size == 0:
        unseen = view.get("unseen", {})
        if hasattr(unseen, "items"):
            for char, count in unseen.items():
                unseen_score += TILE_VALUES.get(char.upper(), 0) * count
        elif hasattr(unseen, "__iter__"):
            for char in unseen:
                unseen_score += TILE_VALUES.get(char.upper(), 0)

    # Helper functions for lookahead search
    def update_grid(g, move):
        if not g or move["kind"] != "play" or not move.get("tiles"):
            return g
        new_grid = [row[:] for row in g]
        for r, c, letter, is_blank in move["tiles"]:
            new_grid[r][c] = [letter, is_blank]
        return new_grid

    def get_open_tws(g):
        if not g:
            return TWS.copy()
        return {pos for pos in TWS if g[pos[0]][pos[1]] is None}

    def get_next_rack(rack, move):
        if move["kind"] != "play" or not move.get("tiles"):
            return rack[:]
        new_rack = [c.upper() for c in rack]
        for r, c, letter, is_blank in move["tiles"]:
            val_to_remove = "?" if is_blank else letter.upper()
            if val_to_remove in new_rack:
                new_rack.remove(val_to_remove)
        return new_rack

    def get_heuristic_utility(move, g, open_tws, b_size):
        score = move["score"]
        leave = [c.upper() for c in move["leave"]] if move["leave"] is not None else []

        if b_size == 0:
            if not leave:
                leave_val = 2.0 * unseen_score
            else:
                leave_val = -2.0 * sum(TILE_VALUES.get(c, 0) for c in leave)
            utility = score + leave_val
        else:
            leave_val = 0.0
            if leave:
                has_q = "Q" in leave
                has_u = "U" in leave
                for char in leave:
                    val = VAL.get(char, 0.0)
                    if char == "Q" and has_u:
                        val = 2.0
                    elif char == "U" and has_q:
                        val = 1.0
                    leave_val += val

                if has_q and not has_u:
                    leave_val -= 8.0

                # Penalize duplicate letters
                counts = {}
                for char in leave:
                    if char != "?":
                        counts[char] = counts.get(char, 0) + 1
                for char, count in counts.items():
                    if count > 1:
                        leave_val -= (count - 1) * (1.0 if char == "S" else 2.5)

                # Maintain a healthy vowel/consonant balance (target ~43% vowels)
                vowels = 0
                consonants = 0
                for c in leave:
                    if c in VOWELS:
                        vowels += 1
                    elif c != "?":
                        consonants += 1

                total = vowels + consonants
                if total > 1:
                    ideal_v = round(total * 0.43)
                    leave_val -= abs(vowels - ideal_v) * 2.0

            leave_weight = max(0.0, min(1.0, b_size / 7.0))
            utility = score + leave_val * leave_weight

        # Defensive check: Avoid opening empty Triple Word Score squares
        tws_penalty = 0.0
        if move["kind"] == "play" and move.get("tiles") and g:
            move_coords = {(t[0], t[1]) for t in move["tiles"]}
            tws_dists = {}
            for r, col, _, _ in move["tiles"]:
                if r in (0, 7, 14):
                    for tc in (0, 7, 14):
                        if (r, tc) in open_tws and (r, tc) not in move_coords:
                            dist = abs(col - tc)
                            if 1 <= dist <= 3:
                                step = 1 if tc > col else -1
                                blocked = False
                                for c_mid in range(col + step, tc, step):
                                    if g[r][c_mid] is not None:
                                        blocked = True
                                        break
                                if not blocked:
                                    tws_dists[(r, tc)] = min(
                                        tws_dists.get((r, tc), 99), dist
                                    )
                if col in (0, 7, 14):
                    for tr in (0, 7, 14):
                        if (tr, col) in open_tws and (tr, col) not in move_coords:
                            dist = abs(r - tr)
                            if 1 <= dist <= 3:
                                step = 1 if tr > r else -1
                                blocked = False
                                for r_mid in range(r + step, tr, step):
                                    if g[r_mid][col] is not None:
                                        blocked = True
                                        break
                                if not blocked:
                                    tws_dists[(tr, col)] = min(
                                        tws_dists.get((tr, col), 99), dist
                                    )

            for (tr, tc), dist in tws_dists.items():
                tws_penalty += 10.0 if dist == 1 else (5.0 if dist == 2 else 3.0)

        utility -= tws_penalty
        return utility

    def eval_endgame_move_heuristic(move, rack):
        rem_rack = get_next_rack(rack, move)
        if not rem_rack:
            return move["score"] + 15.0
        return move["score"] - 2.0 * sum(TILE_VALUES.get(c, 0) for c in rem_rack)

    # Setup lookahead budget and RNG
    rng = random.Random(view["cgp"])
    budget = {"calls": 0, "limit": 25}

    # 1. Deterministic Endgame Search
    if bag_size == 0:
        try:
            world = tools.sample_world(view["cgp"], rng)
        except Exception:
            world = None

        if world is not None:
            our_rack = list(view.get("rack", []))
            opp_rack = []
            unseen = view.get("unseen", {})
            if hasattr(unseen, "items"):
                for char, count in unseen.items():
                    opp_rack.extend([char.upper()] * count)
            elif hasattr(unseen, "__iter__"):
                for char in unseen:
                    opp_rack.extend([char.upper()])

            moves_with_heur = []
            for idx, m in enumerate(moves):
                heur = eval_endgame_move_heuristic(m, our_rack)
                moves_with_heur.append((heur, idx, m))
            moves_with_heur.sort(key=lambda x: x[0], reverse=True)

            num_candidates = min(12, len(moves_with_heur))
            candidates = [m for _, _, m in moves_with_heur[:num_candidates]]

            best_move_idx = 0
            best_val = -float("inf")

            for idx, m in enumerate(candidates):
                our_rack_1 = get_next_rack(our_rack, m)
                try:
                    w1 = tools.play(world, m)
                except Exception:
                    continue

                if tools.over(w1):
                    val = tools.spread(w1, view["me"])
                else:
                    if budget["calls"] < budget["limit"]:
                        try:
                            opp_moves = tools.legal(w1)
                            budget["calls"] += 1
                        except Exception:
                            opp_moves = []

                        if not opp_moves:
                            val = (
                                tools.spread(w1, view["me"])
                                - 2.0 * sum(TILE_VALUES.get(c, 0) for c in our_rack_1)
                                + 2.0 * sum(TILE_VALUES.get(c, 0) for c in opp_rack)
                            )
                        else:
                            opp_moves_heur = []
                            for om in opp_moves:
                                h = eval_endgame_move_heuristic(om, opp_rack)
                                opp_moves_heur.append((h, om))
                            opp_moves_heur.sort(key=lambda x: x[0], reverse=True)

                            best_opp_m = opp_moves_heur[0][1]
                            opp_rack_1 = get_next_rack(opp_rack, best_opp_m)
                            try:
                                w2 = tools.play(w1, best_opp_m)
                            except Exception:
                                w2 = None

                            if w2 is None:
                                val = (
                                    tools.spread(w1, view["me"])
                                    - 2.0
                                    * sum(TILE_VALUES.get(c, 0) for c in our_rack_1)
                                    + 2.0 * sum(TILE_VALUES.get(c, 0) for c in opp_rack)
                                )
                            elif tools.over(w2):
                                val = tools.spread(w2, view["me"])
                            else:
                                if budget["calls"] < budget["limit"]:
                                    try:
                                        our_resp_moves = tools.legal(w2)
                                        budget["calls"] += 1
                                    except Exception:
                                        our_resp_moves = []

                                    if not our_resp_moves:
                                        val = (
                                            tools.spread(w2, view["me"])
                                            - 2.0
                                            * sum(
                                                TILE_VALUES.get(c, 0)
                                                for c in our_rack_1
                                            )
                                            + 2.0
                                            * sum(
                                                TILE_VALUES.get(c, 0)
                                                for c in opp_rack_1
                                            )
                                        )
                                    else:
                                        best_resp = max(
                                            our_resp_moves,
                                            key=lambda rm: eval_endgame_move_heuristic(
                                                rm, our_rack_1
                                            ),
                                        )
                                        our_rack_2 = get_next_rack(
                                            our_rack_1, best_resp
                                        )
                                        try:
                                            w3 = tools.play(w2, best_resp)
                                        except Exception:
                                            w3 = None

                                        if w3 is None:
                                            val = (
                                                tools.spread(w2, view["me"])
                                                - 2.0
                                                * sum(
                                                    TILE_VALUES.get(c, 0)
                                                    for c in our_rack_1
                                                )
                                                + 2.0
                                                * sum(
                                                    TILE_VALUES.get(c, 0)
                                                    for c in opp_rack_1
                                                )
                                            )
                                        elif tools.over(w3):
                                            val = tools.spread(w3, view["me"])
                                        else:
                                            val = (
                                                tools.spread(w3, view["me"])
                                                - 2.0
                                                * sum(
                                                    TILE_VALUES.get(c, 0)
                                                    for c in our_rack_2
                                                )
                                                + 2.0
                                                * sum(
                                                    TILE_VALUES.get(c, 0)
                                                    for c in opp_rack_1
                                                )
                                            )
                                else:
                                    val = (
                                        tools.spread(w2, view["me"])
                                        - 2.0
                                        * sum(TILE_VALUES.get(c, 0) for c in our_rack_1)
                                        + 2.0
                                        * sum(TILE_VALUES.get(c, 0) for c in opp_rack_1)
                                    )
                    else:
                        val = (
                            tools.spread(w1, view["me"])
                            - 2.0 * sum(TILE_VALUES.get(c, 0) for c in our_rack_1)
                            + 2.0 * sum(TILE_VALUES.get(c, 0) for c in opp_rack)
                        )

                if val > best_val:
                    best_val = val
                    best_move_idx = idx

            return moves.index(candidates[best_move_idx])

    # 2. Midgame Lookahead Search
    else:
        moves_with_heur = []
        for idx, m in enumerate(moves):
            heur = get_heuristic_utility(m, grid, open_tws_board, bag_size)
            moves_with_heur.append((heur, idx, m))
        moves_with_heur.sort(key=lambda x: x[0], reverse=True)

        if len(moves) <= 1:
            return moves_with_heur[0][1]

        num_candidates = min(10, len(moves_with_heur))
        candidates = moves_with_heur[:num_candidates]

        worlds = []
        for _ in range(2):
            try:
                worlds.append(tools.sample_world(view["cgp"], rng))
            except Exception:
                pass

        if not worlds:
            return moves_with_heur[0][1]

        best_move_idx = candidates[0][1]
        best_avg_utility = -float("inf")

        for heur_val, idx, m in candidates:
            utilities = []
            for world in worlds:
                if budget["calls"] >= budget["limit"]:
                    utilities.append(heur_val)
                    continue

                try:
                    w1 = tools.play(world, m)
                    opp_moves = tools.legal(w1)
                    budget["calls"] += 1
                except Exception:
                    utilities.append(heur_val)
                    continue

                if not opp_moves:
                    utilities.append(heur_val)
                else:
                    w1_grid = update_grid(grid, m)
                    w1_open_tws = get_open_tws(w1_grid)

                    max_opp_utility = -float("inf")
                    for om in opp_moves:
                        om_heur = get_heuristic_utility(
                            om, w1_grid, w1_open_tws, bag_size
                        )
                        if om_heur > max_opp_utility:
                            max_opp_utility = om_heur

                    utilities.append(heur_val - max_opp_utility)

            avg_utility = sum(utilities) / len(utilities)
            if avg_utility > best_avg_utility:
                best_avg_utility = avg_utility
                best_move_idx = idx

        return best_move_idx
# CADENCE:END
